    41  // big <-> little-endian and store it in a memory position.  Sizes supported: 1, 2, 4, 8 bytes.
    42  void swap_store(void *dest, const void *pa, int size) {
    43      uint8_t* pa_ = (uint8_t*)pa;
    44      uint8_t* pa2_ = malloc((size_t)size);
    45
    46      bool little_endian = is_little_endian();
    47      if (little_endian) {
    48          switch (size) {
    49              case 8:
    50                  pa2_[0] = pa_[7];
    51                  pa2_[1] = pa_[6];
    52                  pa2_[2] = pa_[5];
    53                  pa2_[3] = pa_[4];
    54                  pa2_[4] = pa_[3];
    55                  pa2_[5] = pa_[2];
    56                  pa2_[6] = pa_[1];
    57                  pa2_[7] = pa_[0];
    58                  break;
    59              case 4:
    60                  pa2_[0] = pa_[3];
    61                  pa2_[1] = pa_[2];
    62                  pa2_[2] = pa_[1];
    63                  pa2_[3] = pa_[0];
    64                  break;
    65              case 2:
    66                  pa2_[0] = pa_[1];
    67                  pa2_[1] = pa_[0];
    68                  break;
    69              case 1:
    70                  pa2_[0] = pa_[1];
    71                  break;
    72              default:
    73                  fprintf(stderr, "Unhandled size: %d\n", size);
    74          }
    75      }
    76      memcpy(dest, pa2_, size);
    77      free(pa2_);
    78  }
