   113  void *new_header_frame(blosc2_schunk *schunk, blosc2_frame *frame) {
   114    if (frame == NULL) {
   115      return NULL;
   116    }
   117    uint8_t* h2 = calloc(FRAME_HEADER_MINLEN, 1);
   118    uint8_t* h2p = h2;
   119
   120    // The msgpack header starts here
   121    *h2p = 0x90;  // fixarray...
   122    *h2p += 13;   // ...with 13 elements
   123    h2p += 1;
   124
   125    // Magic number
   126    *h2p = 0xa0 + 8;  // str with 8 elements
   127    h2p += 1;
   128    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   129      return NULL;
   130    }
   131    strcpy((char*)h2p, "b2frame");
   132    h2p += 8;
   133
   134    // Header size
   135    *h2p = 0xd2;  // int32
   136    h2p += 1 + 4;
   137    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   138      return NULL;
   139    }
   140
   141    // Total frame size
   142    *h2p = 0xcf;  // uint64
   143    // Fill it with frame->len which is known *after* the creation of the frame (e.g. when updating the header)
   144    int64_t flen = frame->len;
   145    swap_store(h2 + FRAME_LEN, &flen, sizeof(flen));
   146    h2p += 1 + 8;
   147    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   148      return NULL;
   149    }
   150
   151    // Flags
   152    *h2p = 0xa0 + 4;  // str with 4 elements
   153    h2p += 1;
   154    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   155      return NULL;
   156    }
   157
   158    // General flags
   159    *h2p = BLOSC2_VERSION_FRAME_FORMAT;  // version
   160    *h2p += 0x20;  // 64-bit offsets
   835    return coffsets;
   836  }
