   839  int frame_update_header(blosc2_frame* frame, blosc2_schunk* schunk, bool new) {
   840    uint8_t* framep = frame->sdata;
   841    uint8_t header[FRAME_HEADER_MINLEN];
   842
   843    if (frame->len <= 0) {
   844      return -1;
   845    }
   846
   847    if (new && schunk->cbytes > 0) {
   848      fprintf(stderr, "Error: new metalayers cannot be added after actual data has been appended\n");
   849      return -1;
   850    }
   851
   852    if (frame->sdata == NULL) {
   853      size_t rbytes = 0;
   854      FILE* fp = fopen(frame->fname, "rb");
   855      if (fp != NULL) {
   856        rbytes = fread(header, 1, FRAME_HEADER_MINLEN, fp);
   857        fclose(fp);
   858      }
   859      (void) rbytes;
   860      if (rbytes != FRAME_HEADER_MINLEN) {
   861        return -1;
   862      }
   863      framep = header;
   864    }
   865    uint32_t prev_h2len;
   866    swap_store(&prev_h2len, framep + FRAME_HEADER_LEN, sizeof(prev_h2len));
   867
   868    // Build a new header
   869    uint8_t* h2 = new_header_frame(schunk, frame);
   870    uint32_t h2len;
   871    swap_store(&h2len, h2 + FRAME_HEADER_LEN, sizeof(h2len));
   872
   873    // The frame length is outdated when adding a new metalayer, so update it
   874    if (new) {
   875      int64_t frame_len = h2len;  // at adding time, we only have to worry of the header for now
   876      swap_store(h2 + FRAME_LEN, &frame_len, sizeof(frame_len));
   877      frame->len = frame_len;
   878    }
   879
   880    if (!new && prev_h2len != h2len) {
   881      fprintf(stderr, "Error: the new metalayer sizes should be equal the existing ones");
   882      return -2;
   883    }
   884
   885    if (frame->sdata == NULL) {
   886      // Write updated header down to file
   887      FILE* fp = fopen(frame->fname, "rb+");
   888      if (fp != NULL) {
   889        fwrite(h2, h2len, 1, fp);
   890        fclose(fp);
   891      }
   892    }
   893    else {
   894      if (new) {
   895        frame->sdata = realloc(frame->sdata, h2len);
   896      }
   897      memcpy(frame->sdata, h2, h2len);
   898    }
   899    free(h2);
   900
   901    return 1;
   902  }
