   905  /* Get the (compressed) usermeta chunk out of a frame */
   906  int32_t frame_get_usermeta(blosc2_frame* frame, uint8_t** usermeta) {
   907    int32_t header_len;
   908    int64_t frame_len;
   909    int64_t nbytes;
   910    int64_t cbytes;
   911    int32_t chunksize;
   912    int32_t nchunks;
   913    int ret = get_header_info(frame, &header_len, &frame_len, &nbytes, &cbytes, &chunksize, &nchunks,
   914                              NULL, NULL, NULL, NULL, NULL);
   915    if (ret < 0) {
   916      fprintf(stderr, "Unable to get the header info from frame");
   917      return -1;
   918    }
   919    int64_t trailer_offset = get_trailer_offset(frame, header_len, cbytes);
   920    if (trailer_offset < 0) {
   921      fprintf(stderr, "Unable to get the trailer offset from frame");
   922      return -1;
   923    }
   924
   925    // Get the size of usermeta (inside the trailer)
   926    int32_t usermeta_len_network;
   927    if (frame->sdata != NULL) {
   928      memcpy(&usermeta_len_network, frame->sdata + trailer_offset + FRAME_TRAILER_USERMETA_LEN_OFFSET, sizeof(int32_t));
   929    } else {
   930      FILE* fp = fopen(frame->fname, "rb");
   931      fseek(fp, trailer_offset + FRAME_TRAILER_USERMETA_LEN_OFFSET, SEEK_SET);
   932      size_t rbytes = fread(&usermeta_len_network, 1, sizeof(int32_t), fp);
   933      if (rbytes != sizeof(int32_t)) {
   934        fprintf(stderr, "Cannot access the usermeta_len out of the fileframe.\n");
   935        fclose(fp);
   936        return -1;
   937      }
   938      fclose(fp);
   939    }
   940    int32_t usermeta_len;
   941    swap_store(&usermeta_len, &usermeta_len_network, sizeof(int32_t));
   942
   943    if (usermeta_len == 0) {
   944      *usermeta = NULL;
   945      return 0;
   946    }
   947
   948    *usermeta = malloc(usermeta_len);
   949    if (frame->sdata != NULL) {
   950      memcpy(*usermeta, frame->sdata + trailer_offset + FRAME_TRAILER_USERMETA_OFFSET, usermeta_len);
   951    }
   952    else {
   953      FILE* fp = fopen(frame->fname, "rb+");
   954      fseek(fp, trailer_offset + FRAME_TRAILER_USERMETA_OFFSET, SEEK_SET);
   955      size_t rbytes = fread(*usermeta, 1, usermeta_len, fp);
   956      if (rbytes != (size_t)usermeta_len) {
   957        fprintf(stderr, "Error: cannot read the complete usermeta chunk in frame. %ld != %ld \n",
   958                (long)rbytes, (long)usermeta_len);
   959        return -1;
   960      }
   961      fclose(fp);
   962    }
   963
   964    return usermeta_len;
   965  }
