  1291  int64_t get_coffset(blosc2_frame* frame, int32_t header_len, int64_t cbytes, int32_t nchunk) {
  1292    // Get the offset to nchunk
  1293    int64_t offset;
  1294    uint8_t *coffsets = get_coffsets(frame, header_len, cbytes, NULL);
  1295    if (coffsets == NULL) {
  1296      fprintf(stderr, "Error: cannot get the offset for chunk %d for the frame\n", nchunk);
  1297      return -3;
  1298    }
  1299
  1300    int rc = blosc_getitem(coffsets, nchunk, 1, &offset);
  1301    if (rc < 0) {
  1302      size_t nbytes_, cbytes_, blocksize_;
  1303      blosc_cbuffer_sizes(coffsets, &nbytes_, &cbytes_, &blocksize_);
  1304      fprintf(stderr, "Error: problems retrieving a chunk offset");
  1305      return -4;
  1306    }
  1307    return offset;
  1308  }
