  1310  /* Return a compressed chunk that is part of a frame in the `chunk` parameter.
  1311   * If the frame is disk-based, a buffer is allocated for the (compressed) chunk,
  1312   * and hence a free is needed.  You can check if the chunk requires a free with the `needs_free`
  1313   * parameter.
  1314   * If the chunk does not need a free, it means that a pointer to the location in frame is returned
  1315   * in the `chunk` parameter.
  1316   *
  1317   * The size of the (compressed) chunk is returned.  If some problem is detected, a negative code
  1318   * is returned instead.
  1319  */
  1320  int frame_get_chunk(blosc2_frame *frame, int nchunk, uint8_t **chunk, bool *needs_free) {
  1321    int32_t header_len;
  1322    int64_t frame_len;
  1323    int64_t nbytes;
  1324    int64_t cbytes;
  1325    int32_t chunksize;
  1326    int32_t nchunks;
  1327
  1328    *chunk = NULL;
  1329    *needs_free = false;
  1330    int ret = get_header_info(frame, &header_len, &frame_len, &nbytes, &cbytes, &chunksize, &nchunks,
  1331                              NULL, NULL, NULL, NULL, NULL);
  1332    if (ret < 0) {
  1333      fprintf(stderr, "unable to get meta info from frame");
  1334      return -1;
  1335    }
  1336
  1337    if (nchunk >= nchunks) {
  1338      fprintf(stderr, "nchunk ('%d') exceeds the number of chunks "
  1339                      "('%d') in frame\n", nchunk, nchunks);
  1340      return -2;
  1341    }
  1342
  1343    // Get the offset to nchunk
  1344    int64_t offset = get_coffset(frame, header_len, cbytes, nchunk);
  1345
  1346    int32_t chunk_cbytes;
  1347    if (frame->sdata == NULL) {
  1348      FILE* fp = fopen(frame->fname, "rb");
  1349      fseek(fp, header_len + offset + BLOSC2_CHUNK_CBYTES, SEEK_SET);
  1350      size_t rbytes = fread(&chunk_cbytes, 1, sizeof(chunk_cbytes), fp);
  1351      if (rbytes != sizeof(chunk_cbytes)) {
  1352        fprintf(stderr, "Cannot read the cbytes for chunk in the fileframe.\n");
  1353        return -5;
  1354      }
  1355      chunk_cbytes = sw32_(&chunk_cbytes);
  1356      *chunk = malloc((size_t)chunk_cbytes);
  1357      fseek(fp, header_len + offset, SEEK_SET);
  1358      rbytes = fread(*chunk, 1, (size_t)chunk_cbytes, fp);
  1359      if (rbytes != (size_t)chunk_cbytes) {
  1360        fprintf(stderr, "Cannot read the chunk out of the fileframe.\n");
  1361        return -6;
  1362      }
  1363      fclose(fp);
  1364      *needs_free = true;
  1365    } else {
  1366      // The chunk is in memory and just one pointer away
  1367      *chunk = frame->sdata + header_len + offset;
  1368      chunk_cbytes = sw32_(*chunk + BLOSC2_CHUNK_CBYTES);
  1369    }
